45	/**********************************************************************
46	 * Function:    eth_send_packet()
47	 *
48	 * Description: Sends a raw Ethernet packet to the CPU Rx FIFO
49	 *
50	 * Returns:     Length of the sent packet
51	 **********************************************************************/
52	uint32_t eth_send_packet (volatile csr_vp_t* csr, eth_raw_packet_t* packet) {
53	   uint32_t i;
54	   uint32_t empty;
55	   if (csr->cpu_fifo->rx->status->tready()) {
56	      i = 0;
57	
58	      csr->cpu_fifo->rx->control->tuser_dst(packet->dst);
59	      csr->cpu_fifo->rx->control->tuser_src(packet->src);
60	      csr->cpu_fifo->rx->control->tuser_bypass_stage(packet->bypass_stage);
61	      csr->cpu_fifo->rx->control->tuser_bypass_all(packet->bypass_all);
62	
63	      while (1) {
64	         csr->cpu_fifo->rx->data_31_0->tdata(*((uint32_t*)(packet->payload + i)));
65	         csr->cpu_fifo->rx->data_63_32->tdata(*((uint32_t*)(packet->payload + i + 4)));
66	         csr->cpu_fifo->rx->data_95_64->tdata(*((uint32_t*)(packet->payload + i + 8)));
67	         csr->cpu_fifo->rx->data_127_96->tdata(*((uint32_t*)(packet->payload + i + 12)));
68	
69	         i += 16;
70	
71	         if (i < packet->len) {
72	            csr->cpu_fifo->rx->control->tkeep(0xFFFF);
73	            csr->cpu_fifo->rx->control->tlast(0);
74	            csr->cpu_fifo->rx->trigger->tvalid(1);
75	         } else {
76	            empty = i - packet->len;
77	            csr->cpu_fifo->rx->control->tkeep(0xFFFF >> empty);
78	            csr->cpu_fifo->rx->control->tlast(1);
79	            csr->cpu_fifo->rx->trigger->tvalid(1);
80	            return packet->len;
81	         }
82	      }
83	   } else {
84	      return 0;
85	   }
86	}
87	
88	/**********************************************************************
89	 * Function:    eth_receive_packet()
90	 *
91	 * Description: Receives a raw Ethernet packet from the CPU Tx FIFO
92	 *
93	 * Returns:     Length of the received packet
94	 **********************************************************************/
95	uint32_t eth_receive_packet (volatile csr_vp_t* csr, eth_raw_packet_t* packet) {
96	   uint32_t len = 0;
97	   uint16_t keep;
98	   packet->dst = 0;
99	   packet->bypass_stage = 0;
100	   packet->bypass_all = 0;
101	   if (csr->cpu_fifo->tx->status->tvalid()) {
102	      packet->src = csr->cpu_fifo->tx->control->tuser_src();
103	      while (1) {
104	         if (len <= ETH_MAX_FRAME_LENGTH - 16) {
105	            *((uint32_t*)(packet->payload + len)) = csr->cpu_fifo->tx->data_31_0->tdata();
106	            *((uint32_t*)(packet->payload + len + 4)) = csr->cpu_fifo->tx->data_63_32->tdata();
107	            *((uint32_t*)(packet->payload + len + 8)) = csr->cpu_fifo->tx->data_95_64->tdata();
108	            *((uint32_t*)(packet->payload + len + 12)) = csr->cpu_fifo->tx->data_127_96->tdata();
109	         }
110	
111	         if (csr->cpu_fifo->tx->control->tlast()) {
112	            keep = csr->cpu_fifo->tx->control->tkeep();
113	            while (keep & 1) {
114	                len++;
115	                keep >>= 1;
116	            }
117	            packet->len = (len < ETH_MAX_FRAME_LENGTH) ? len : ETH_MAX_FRAME_LENGTH;
118	            csr->cpu_fifo->tx->trigger->tready(1);
119	            return packet->len;
120	         } else {
121	            len += 16;
122	            csr->cpu_fifo->tx->trigger->tready(1);
123	         }
124	      }
125	   } else {
126	      return 0;
127	   }
