42	
43	#include "network.h"
44	
45	/**********************************************************************
46	 * Function:    net_str_parse_ip()
47	 *
48	 * Description: Parses IP address from string (xxx.xxx.xxx.xxx)
49	 *
50	 * Returns:     1 if successful, 0 otherwise
51	 * write function without using scanf sscanf from stdlib
52	 **********************************************************************/
53	uint8_t net_str_parse_ip(const char* str, ip_t *ip) {
54	   int part = 0;
55	   int value = 0;
56	   ip_t temp_ip = {0, 0, 0, 0};
57	   while (*str != '\n' && *str != '\0') {
58	      if (*str >= '0' && *str <= '9') {
59	         value = value * 10 + (*str - '0');
60	         if (value > 255) {
61	            return 0; // Invalid value
62	         }
63	      } else if (*str == '.') {
64	         if (part >= 3) {
65	            return 0; // Too many parts
66	         }
67	         temp_ip[part++] = (uint8_t)value;
68	         value = 0;
69	      } else {
70	         return 0; // Invalid character
71	      }
72	      str++;
73	   }
74	   if (part != 3) {
75	      return 0; // Not enough parts
76	   }
77	   (*ip)[0] = temp_ip[0];
78	   (*ip)[1] = temp_ip[1];
79	   (*ip)[2] = temp_ip[2];
80	   (*ip)[3] = (uint8_t)value;
81	   return 1; // Success
82	}
83	
84	/**********************************************************************
85	 * Function:    net_calculate_checksum()
86	 *
87	 * Description: Calculates 16-bit one's complement checksum
88	 *
89	 * Returns:     Checksum
90	 **********************************************************************/
91	uint16_t net_calculate_checksum(const uint8_t *data, size_t len) {
92	   uint32_t sum = 0;
93	
94	   size_t i;
95	   for (i = 0; i + 1 < len; i += 2) {
96	      uint16_t word = ((uint16_t)data[i] << 8) | data[i + 1];
97	      sum += word;
98	
99	      if (sum > 0xFFFF) {
100	         sum = (sum & 0xFFFF) + 1;
101	      }
102	   }
103	
104	   if (i < len) {
105	      uint16_t word = ((uint16_t)data[i] << 8);
106	      sum += word;
107	
108	      if (sum > 0xFFFF) {
109	         sum = (sum & 0xFFFF) + 1;
110	      }
111	   }
112	
113	   return (uint16_t)(~sum & 0xFFFF);
114	}
115	
116	/**********************************************************************
117	 * Function:    net_parse_packet_header()
118	 *
119	 * Description: Parses Ethernet packet header
120	 *
121	 * Returns:     Protocol type
122	 **********************************************************************/
123	net_protocol_t net_parse_packet_header (eth_raw_packet_t* packet) {
124	   net_hdr_eth_t* hdr_eth = (net_hdr_eth_t*)(packet->payload);
125	   net_hdr_ipv4_t* hdr_ipv4 = (net_hdr_ipv4_t*)(packet->payload + sizeof(net_hdr_eth_t));
126	   if (hdr_eth->ethertype[0] == 0x08 && hdr_eth->ethertype[1] == 0x06) {
127	      return NET_PROTO_ARP;
128	   } else if (hdr_eth->ethertype[0] == 0x08 && hdr_eth->ethertype[1] == 0x00 && hdr_ipv4->version == 4) {
129	      if (hdr_ipv4->protocol == 1) {
130	         return NET_PROTO_ICMP;
131	      } else if (hdr_ipv4->protocol == 17) {
132	         return NET_PROTO_UDP;
133	      }
134	   }
135	   return NET_PROTO_UNKNOWN;
136	}
137	
138	/**********************************************************************
139	 * Function:    net_process_arp()
140	 *
141	 * Description: Executes Address Resolution Protocol by:
142	 *               - processing ARP request, and generating ARP reply, or
143	 *               - processing ARP reply, and updating ARP cache
144	 * Returns:     1 if ARP reply is generated, 0 otherwise
145	 **********************************************************************/
146	uint8_t net_process_arp (net_config_t*     config,
147	                         net_arp_cache_t*  arp_cache,
148	                         eth_raw_packet_t* rx_packet,
149	                         eth_raw_packet_t* tx_packet) {
150	   // Get Ethernet and ARP headers to RX and TX packets
151	   net_hdr_eth_t* rx_hdr_eth = (net_hdr_eth_t*)(rx_packet->payload);
152	   net_hdr_arp_t* rx_hdr_arp = (net_hdr_arp_t*)(rx_packet->payload + sizeof(net_hdr_eth_t));
153	   net_hdr_eth_t* tx_hdr_eth = (net_hdr_eth_t*)(tx_packet->payload);
154	   net_hdr_arp_t* tx_hdr_arp = (net_hdr_arp_t*)(tx_packet->payload + sizeof(net_hdr_eth_t));
155	   // Check if hardware type is Ethernet (0x0001)
156	   if (rx_hdr_arp->htype[0] != 0x00 || rx_hdr_arp->htype[1] != 0x01) {
157	      return 0;
158	   }
159	   // Check if protocol type is IPv4 (0x0800)
160	   if (rx_hdr_arp->ptype[0] != 0x08 || rx_hdr_arp->ptype[1] != 0x00) {
161	      return 0;
162	   }
163	   // Check if targeted to my IP
164	   if (memcmp(rx_hdr_arp->tpa, config->ip, 4) != 0) {
165	      return 0;
166	   }
167	   // Check if opcode is request (0x0001)
168	   if (rx_hdr_arp->oper[0] == 0x00 && rx_hdr_arp->oper[1] == 0x01) {
169	      // Assemble ARP reply
170	      tx_packet->dst = rx_packet->src;
171	      tx_packet->bypass_all = 1;
172	      tx_packet->len = 42;
173	      memcpy(tx_hdr_eth->dst_mac, rx_hdr_arp->sha, 6);
174	      memcpy(tx_hdr_eth->src_mac, config->mac, 6);
175	      tx_hdr_eth->ethertype[0] = 0x08;
176	      tx_hdr_eth->ethertype[1] = 0x06;
177	      tx_hdr_arp->htype[0] = 0x00;
178	      tx_hdr_arp->htype[1] = 0x01;
179	      tx_hdr_arp->ptype[0] = 0x08;
180	      tx_hdr_arp->ptype[1] = 0x00;
181	      tx_hdr_arp->hlen = 0x06;
182	      tx_hdr_arp->plen = 0x04;
183	      tx_hdr_arp->oper[0] = 0x00;
184	      tx_hdr_arp->oper[1] = 0x02;
185	      memcpy(tx_hdr_arp->sha, config->mac, 6);
186	      memcpy(tx_hdr_arp->spa, config->ip, 4);
187	      memcpy(tx_hdr_arp->tha, rx_hdr_arp->sha, 6);
188	      memcpy(tx_hdr_arp->tpa, rx_hdr_arp->spa, 4);
189	      return 1;
190	   // else, check if opcode is response (0x0002)
191	   } else if (rx_hdr_arp->oper[0] == 0x00 && rx_hdr_arp->oper[1] == 0x02) {
192	      // TODO: update ARP cache
193	   }
194	   return 0;
195	}
196	
197	/**********************************************************************
198	 * Function:    net_process_icmp()
199	 *
200	 * Description: Executes Internet Control Message Protocol by:
201	 *               - processing ICMP Echo, and generating Echo reply
202	 * Returns:     1 if ICMP Echo reply is generated, 0 otherwise
203	 **********************************************************************/
204	uint8_t net_process_icmp (net_config_t*     config,
205	                          eth_raw_packet_t* rx_packet,
206	                          eth_raw_packet_t* tx_packet) {
207	   // Get Ethernet, IPv4 and ICMP headers to RX and TX packets
208	   net_hdr_eth_t* rx_hdr_eth = (net_hdr_eth_t*)(rx_packet->payload);
209	   net_hdr_ipv4_t* rx_hdr_ipv4 = (net_hdr_ipv4_t*)(rx_packet->payload + sizeof(net_hdr_eth_t));
210	   net_hdr_icmp_t* rx_hdr_icmp = (net_hdr_icmp_t*)(rx_packet->payload + sizeof(net_hdr_eth_t) + sizeof(net_hdr_ipv4_t));
211	   net_hdr_eth_t* tx_hdr_eth = (net_hdr_eth_t*)(tx_packet->payload);
212	   net_hdr_ipv4_t* tx_hdr_ipv4 = (net_hdr_ipv4_t*)(tx_packet->payload + sizeof(net_hdr_eth_t));
213	   net_hdr_icmp_t* tx_hdr_icmp = (net_hdr_icmp_t*)(tx_packet->payload + sizeof(net_hdr_eth_t) + sizeof(net_hdr_ipv4_t));
214	   uint16_t checksum;
215	   // Check if targeted to my IP
216	   if (memcmp(rx_hdr_ipv4->daddr, config->ip, 4) != 0) {
217	      return 0;
218	   }
219	   // Check if type is Echo request
220	   if (rx_hdr_icmp->type == 0x08 && rx_hdr_icmp->code == 0x00) {
221	      // Assemble ICMP Echo reply
222	      tx_packet->dst = rx_packet->src;
223	      tx_packet->bypass_all = 1;
224	      tx_packet->len = rx_packet->len;
225	      memcpy(tx_hdr_eth->dst_mac, rx_hdr_eth->src_mac, 6);
226	      memcpy(tx_hdr_eth->src_mac, config->mac, 6);
227	      tx_hdr_eth->ethertype[0] = 0x08;
228	      tx_hdr_eth->ethertype[1] = 0x00;
229	      tx_hdr_ipv4->ihl = 5;
230	      tx_hdr_ipv4->version = 4;
231	      tx_hdr_ipv4->tos = 0x00;
232	      tx_hdr_ipv4->tot_len[0] = rx_hdr_ipv4->tot_len[0];
233	      tx_hdr_ipv4->tot_len[1] = rx_hdr_ipv4->tot_len[1];
234	      tx_hdr_ipv4->id[0] = 0x00;
235	      tx_hdr_ipv4->id[1] = 0x00;
236	      tx_hdr_ipv4->frag_off = 0;
237	      tx_hdr_ipv4->ttl = 0xFF;
238	      tx_hdr_ipv4->protocol = 1;
239	      tx_hdr_ipv4->check[0] = 0x00;
240	      tx_hdr_ipv4->check[1] = 0x00;
241	      memcpy(tx_hdr_ipv4->saddr, config->ip, 4);
242	      memcpy(tx_hdr_ipv4->daddr, rx_hdr_ipv4->saddr, 4);
243	      checksum = net_calculate_checksum((uint8_t*)(tx_packet->payload + sizeof(net_hdr_eth_t)), 20);
244	      tx_hdr_ipv4->check[0] = (checksum >> 8) & 0xFF;
245	      tx_hdr_ipv4->check[1] = checksum & 0xFF;
246	      tx_hdr_icmp->type = 0x00;
247	      tx_hdr_icmp->code = 0x00;
248	      tx_hdr_icmp->checksum[0] = 0x00;
249	      tx_hdr_icmp->checksum[1] = 0x00;
250	      tx_hdr_icmp->id[0] = rx_hdr_icmp->id[0];
251	      tx_hdr_icmp->id[1] = rx_hdr_icmp->id[1];
252	      tx_hdr_icmp->sequence[0] = rx_hdr_icmp->sequence[0];
253	      tx_hdr_icmp->sequence[1] = rx_hdr_icmp->sequence[1];
254	      memcpy(tx_packet->payload + sizeof(net_hdr_eth_t) + sizeof(net_hdr_ipv4_t) + sizeof(net_hdr_icmp_t),
255	             rx_packet->payload + sizeof(net_hdr_eth_t) + sizeof(net_hdr_ipv4_t) + sizeof(net_hdr_icmp_t), rx_packet->len - 42);
256	      checksum = net_calculate_checksum((uint8_t*)tx_hdr_icmp, rx_packet->len - 34);
257	      tx_hdr_icmp->checksum[0] = (checksum >> 8) & 0xFF;
258	      tx_hdr_icmp->checksum[1] = checksum & 0xFF;
259	      return 1;
260	   } else {
261	      return 0;
262	   }
263	}
