111	   uint8_t out[32];
112	   int pass = 1;
113	
114	   struct {
115	      const char *input;
116	      const uint8_t expected[32];
117	   } tests[] = {
118	      // RFC 7693 official test vectors (BLAKE2s-256)
119	      {
120	         "", // empty string
121	         {0x69, 0x21, 0x7a, 0x30, 0x79, 0x90, 0x80, 0x94,
122	         0xe1, 0x11, 0x21, 0xd0, 0x42, 0x35, 0x4a, 0x7c,
123	         0x1f, 0x55, 0xb6, 0x48, 0x2c, 0xa1, 0xa5, 0x1e,
124	         0x1b, 0x25, 0x0d, 0xfd, 0x1e, 0xd0, 0xee, 0xf9}
125	      },
126	      {
127	         "abc",
128	         {0x50, 0x8c, 0x5e, 0x8c, 0x32, 0x7c, 0x14, 0xe2,
129	         0xe1, 0xa7, 0x2b, 0xa3, 0x4e, 0xeb, 0x45, 0x2f,
130	         0x37, 0x45, 0x8b, 0x20, 0x9e, 0xd6, 0x3a, 0x29,
131	         0x4d, 0x99, 0x9b, 0x4c, 0x86, 0x67, 0x59, 0x82}
132	      }
133	   };
134	
135	   size_t num_tests = sizeof(tests) / sizeof(tests[0]);
136	
137	   for (size_t i = 0; i < num_tests; i++) {
138	      const char *msg = tests[i].input;
139	      const uint8_t *expected = tests[i].expected;
140	
141	      // Compute hash
