761	   csr->cryptokey_table->entry[entry_idx]->decrypt_key_63_32->key(decrypt_key_63_32);
762	   csr->cryptokey_table->entry[entry_idx]->decrypt_key_31_0->key(decrypt_key_31_0);
763	
764	   uart_send(csr, "  Reset send/recv counters? (y/n) [n]: ");
765	   while (!uart_recv(csr, uart_rx_data));
766	   if (uart_rx_data[0] == 'y' || uart_rx_data[0] == 'Y') {
767	      csr->cryptokey_table->entry[entry_idx]->send_cnt_63_32->cnt(0);
768	      csr->cryptokey_table->entry[entry_idx]->send_cnt_31_0->cnt(0);
