42	
43	#include "uart.h"
44	
45	/**********************************************************************
46	 * Function:    uart_send_char()
47	 *
48	 * Description: Sends a single characters to UART HW Controller
49	 *
50	 * Returns:     None
51	 **********************************************************************/
52	void uart_send_char(volatile csr_vp_t* csr, char c) {
53	   // wait for HW "not busy", then send the byte/character
54	   while (csr->uart->tx->busy());
55	   csr->uart->tx->data(c);
56	}
57	
58	/**********************************************************************
59	 * Function:    uart_send_hex()
60	 *
61	 * Description: Converts decimal to a string of ASCII HEX characters
62	 *              and sends them to UART
63	 *
64	 * Returns:     None
65	 **********************************************************************/
66	void uart_send_hex(volatile csr_vp_t* csr, unsigned int val, int digits) {
67	   for (int i = (4*digits) - 4; i >= 0; i -= 4)
68	      uart_send_char(csr, "0123456789ABCDEF"[(val >> i) % 16]);
69	}
70	
71	/**********************************************************************
72	 * Function:    uart_send_hex_bytes()
73	 *
74	 * Description: Converts a byte array into ASCII hexadecimal
75	 *              representation and sends it over UART.
76	 *              Each byte is transmitted as two HEX characters
77	 *
78	 * Returns:     None
79	 **********************************************************************/
80	void uart_send_hex_bytes(volatile csr_vp_t* csr, const uint8_t *data, int len) {
81	   const char hex[] = "0123456789ABCDEF";
82	   for (int i = 0; i < len; i++)
83	   {
84	      uint8_t b = data[i];
85	      uart_send_char(csr, hex[b >> 4]);    // high nibble
86	      uart_send_char(csr, hex[b & 0xF]);   // low nibble
87	   }
88	}
89	
90	/**********************************************************************
91	 * Function:    uart_send_dec()
92	 *
93	 * Description: Converts decimal value to a string of
94	 *              ASCII characters and sends them to UART
95	 *
96	 * Returns:     None
97	 **********************************************************************/
98	void uart_send_dec(volatile csr_vp_t* csr, uint32_t val) {
99	   if (val == 0) {
100	      uart_send_char(csr, '0');
101	      return;
102	   }
103	
104	   uint32_t divisor = 1;
105	
106	   while (divisor <= val / 10) {
107	      divisor *= 10;
108	   }
109	
110	   while (divisor > 0) {
111	      uint32_t digit = val / divisor;
112	      uart_send_char(csr, digit + '0');
113	      val -= digit * divisor;
114	      divisor /= 10;
115	   }
116	}
117	
118	/**********************************************************************
119	 * Function:    uart_send()
120	 *
121	 * Description: Sends a string of characters to UART
122	 *
123	 * Returns:     None
124	 **********************************************************************/
125	void uart_send(volatile csr_vp_t* csr, const char *s) {
126	   while (*s) uart_send_char(csr, *(s++));
127	}
128	
129	/**********************************************************************
130	 * Function:    uart_send_ip()
131	 *
132	 * Description: Sends IP address (xxx.xxx.xxx.xxx) to UART
133	 *
134	 * Returns:     None
135	 **********************************************************************/
136	void uart_send_ip(volatile csr_vp_t* csr, const uint8_t *ip) {
137	   uart_send_dec(csr, ip[0]);
138	   uart_send_char(csr, '.');
139	   uart_send_dec(csr, ip[1]);
140	   uart_send_char(csr, '.');
141	   uart_send_dec(csr, ip[2]);
142	   uart_send_char(csr, '.');
143	   uart_send_dec(csr, ip[3]);
144	}
145	
146	/**********************************************************************
147	 * Function:    uart_send_ip()
148	 *
149	 * Description: Sends MAC address (xx:xx:xx:xx:xx:xx) to UART
150	 *
151	 * Returns:     None
152	 **********************************************************************/
153	void uart_send_mac(volatile csr_vp_t* csr, const uint8_t *mac) {
154	   uart_send_hex(csr, mac[0], 2);
155	   uart_send_char(csr, ':');
156	   uart_send_hex(csr, mac[1], 2);
157	   uart_send_char(csr, ':');
158	   uart_send_hex(csr, mac[2], 2);
159	   uart_send_char(csr, ':');
160	   uart_send_hex(csr, mac[3], 2);
161	   uart_send_char(csr, ':');
162	   uart_send_hex(csr, mac[4], 2);
163	   uart_send_char(csr, ':');
164	   uart_send_hex(csr, mac[5], 2);
165	}
166	
167	/**********************************************************************
168	 * Function:    uart_recv()
169	 *
170	 * Description: Receive data from UART HW until <CR> or <CR><LF>
171	 *              arrives, printing echo
172	 *
173	 * Returns:     None
174	 **********************************************************************/
175	uint8_t uart_recv(volatile csr_vp_t* csr, char *s) {
176	   uint32_t uart_rx;
177	
178	   // Check for available data:
179	   uart_rx = csr->uart->rx->full();
180	   if (uart_rx & UART_RX_VALID) {
181	      // if SOP received, ignore RX;
182	      if ((uart_rx & UART_RX_DATA) == UART_SOP)
183	         return 0;
184	
185	      // otherwise, keep reading from UART until user enters <ENTER>,
186	      //  or allocated buffer is exhausted
187	      //  (UART_RXBUF_SIZE-1) opens space to append NULL
188	      int i = 0;
189	      while (i < UART_RXBUF_SIZE-1) {
190	         // Store received character
191	         *s = (char)(uart_rx & UART_RX_DATA);
192	
193	         // <CR> or <CR><LF> indicates end of user input
194	         // Append <LF> and exit
195	         if (*s == '\n') {
196	            s++;
197	            i++;
198	            break;
199	         // On <CR> echo back <CR><LF> and exit
200	         } else if (*s == '\r') {
201	            uart_send_char(csr, '\r');
202	            uart_send_char(csr, '\n');
203	            *s = '\n';
204	            s++;
205	            i++;
206	            break;
207	         } else {
208	            // On <BS> or <DEL> remove previously received
209	            //  character and echo back <BS><SPACE><BS>;
210	            if (*s == '\b' || *s == UART_DEL) {
211	               if (i > 0) {
212	                  s--;
213	                  i--;
214	                  uart_send_char(csr, '\b');
215	                  uart_send_char(csr, ' ');
216	                  uart_send_char(csr, '\b');
217	               }
218	            // otherwise, echo back and append received character
219	            } else {
220	               uart_send_char(csr, *s);
221	               s++;
222	               i++;
223	            }
224	         }
225	
226	         // wait for HW to collect one byte/character
227	         //  (*) due to Clear-on-Read nature of VALID and OFLOW flags,
228	         //      this MUST BE ONE SHOT READ. Otherwise, both data and
229	         //      flags could be lost
230	         //
231	         // (**) since this is a tight loop, we in this case
232	         //      don't need to look at 'uart_rx.fld.oflow'
233	         do {
234	            uart_rx = csr->uart->rx->full();
235	         } while (!(uart_rx & UART_RX_VALID));
236	      };
237	
238	      // Append NULL
239	      *s = '\0';
240	
241	      return i;
242	   } else {
243	      return 0;
244	   }
245	}
246	
247	#ifdef UART_TEST
248	/**********************************************************************
249	 * Function:    uart_test()
250	 *
251	 * Description: Simple test of UART input/output, with gaming mindset.
252	 *              The objectives are to:
253	 *               - test the RTL implementation of all relevant logic
254	 *               - illustrate the handshake between SW and HW
255	 *               - provide a foundation for development of "production"
256	 *                 code for UART resource
257	 *
258	 * Returns:     None
259	 **********************************************************************/
260	void uart_test(volatile csr_vp_t* csr) {
261	   const char *rx_expd = "Mi smo FPGA raja";
262	   char        rx_data[UART_RXBUF_SIZE];
263	   char       *rx_data_ptr;
264	   int         result;
265	
266	   uart_send(csr, (char*)"\r\n\nSelam eduSOC Hackers!\r\n");
267	   uart_send(csr, (char*)"Try guessing 3 times what I'm thinking, then press <ENTER>.\r\n");
268	
269	   for (int i=3; i>0; i--) {
270	      //take input from UART and store it into allocated buffer
271	      rx_data_ptr = &rx_data[0];
272	      while(!uart_recv(csr, rx_data_ptr));
273	
274	      uart_send(csr, (char*)"\r\n\n\tYou entered: ");
275	      uart_send(csr, rx_data_ptr);
276	
277	      // check received data
278	      if (strcmp(rx_expd, rx_data_ptr) == 0) {
279	          //CSR -> gpo.fld.led_off = 0b10; // turn on first LED
280	          uart_send(csr, (char*)"\r\n\t| You hit it! :-)\r\n");
281	          break;
282	
283	      // mismatch
284	      } else {
285	          //CSR -> gpo.fld.led_off = 0b11; // turn off all LEDs
286	          uart_send(csr, (char*)"\r\n\t| Sorry, you missed it.");
287	
288	          if (i>1) {
289	            uart_send(csr, (char*)"\r\n\t| ...Try again. Credit left: ");
290	            uart_send_hex(csr, i-1, 1);
291	            uart_send(csr, (char*)"\r\n\n\n");
292	          }
293	      }
294	   }
295	
296	   uart_send(csr, (char*)"\r\nDONE!\r\n");
297	}
298	#endif // UART_TEST
299	
300	
301	#ifdef RISCV_TEST
302	/**********************************************************************
303	 * Function:    uart_tests_info(int cmd)
304	 *
305	 * Description: Sends RISC-V test info to UART
306	 *
307	 * Returns:     None
308	 **********************************************************************/
309	void uart_tests_info(volatile csr_vp_t* csr, int cmd) {
310	
311	   char *tests_list[] = {
312	    "OK!\r\n\r\n",
313	    "ERROR!\r\n\r\n",
314	    "add", "addi", "and", "andi", "auipc",
315	    "beq", "bge", "bgeu", "blt", "bltu", "bne", "jal", "jalr",
316	    "lb", "lbu", "lh", "lhu", "lui", "lw",
317	    "ma_data", "or", "ori",
318	    "sb", "sh", "simple",
319	    "sll", "slli", "slt", "slti", "sltiu", "sltu",
320	    "sra", "srai", "srl", "srli",
321	    "sub", "sw",
322	    "xor", "xori",
323	    "breakpoint", "csr",
324	    "illegal", "lh-misaligned",
325	    "lw-misaligned", "ma_addr",
326	    "ma_fetch", "mcsr",
327	    "sbreak", "scall",
328	    "sh-misaligned", "shamt",
329	    "sw-misaligned", "zicntr"};
330	
331	   // UART signalizes test start and result
332	   if (cmd == 0 || cmd == 1) {
333	      uart_send(csr, tests_list[cmd]);
334	   }
335	   else {
336	      char message [32];
337	
338	      char *prefix = "Testing: ";
339	      char *mes_ptr = message;
340	      char *tst_ptr = tests_list[cmd];
341	
342	      while (*prefix)
343	      {
344	         *mes_ptr++ = *prefix++;
345	      }
346	
347	      while (*tst_ptr)
348	      {
349	         *mes_ptr++ = *tst_ptr++;
350	      }
351	
352	      *mes_ptr++ =  '\r';
353	      *mes_ptr++ =  '\n';
354	      *mes_ptr++ =  '\0';
355	
356	      uart_send(csr, message);
357	   }
358	}
359	#endif // RISCV_TESTS
