   char *tests_list[] = {
    "OK!\r\n\r\n",
    "ERROR!\r\n\r\n",
    "add", "addi", "and", "andi", "auipc",
    "beq", "bge", "bgeu", "blt", "bltu", "bne", "jal", "jalr",
    "lb", "lbu", "lh", "lhu", "lui", "lw",
